const FPS = {{fps}};
let a = 20, b = 20, last = performance.now();
setInterval(() => {
  const now = performance.now();
  const dt = (now - last) / 1000; last = now;
  a += 120 * dt;              // dt 를 곱한다 — 주사율과 무관
  b += 2;                     // 프레임마다 고정 — 주사율에 끌려간다
  if (a > W()) a = 0; if (b > W()) b = 0;
  ctx.clearRect(0, 0, W(), H());
  ctx.fillStyle = '#4ade80'; ctx.fillRect(a, 40, 26, 26);
  ctx.fillStyle = '#f87171'; ctx.fillRect(b, 100, 26, 26);
  ctx.fillStyle = '#eee'; ctx.font = '13px system-ui';
  ctx.fillText('초록 = dt 곱함 · 빨강 = 프레임 고정 · 지금 ' + FPS + 'fps 흉내', 16, 20);
}, 1000 / FPS);

let last = performance.now();
function frame(now) {
  const dt = (now - last) / 1000;   // 초 단위 경과 시간
  last = now;
  update(dt);
  render();
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

// 나쁨: 프레임이 빠를수록 빨라진다
x += 5;

// 좋음: 초당 300px 로 일정
x += 300 * dt;

let acc = 0;
const STEP = 1 / 60;
function update(dt) {
  acc += Math.min(dt, 0.25);
  while (acc >= STEP) { physics(STEP); acc -= STEP; }   // 항상 같은 크기
}
